import {readFile} from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';
const hash=b=>createHash('sha256').update(b).digest('hex');const need=(v,k)=>{if(!v)throw Error('s0c_evidence_'+k);};
export async function s0cSources(){const seen=new Map();async function visit(file){file=path.relative(process.cwd(),path.resolve(file)).split(path.sep).join('/');if(seen.has(file))return;need(!file.startsWith('../'),'source_path');const b=await readFile(file);seen.set(file,hash(b));if(!/\.(ts|mjs)$/.test(file))return;for(const m of b.toString().matchAll(/(?:from\s*|import\s*\()\s*['"](\.[^'"]+)['"]/g)){let next=path.resolve(path.dirname(file),m[1]);if(next.endsWith('.js'))next=next.slice(0,-3)+'.ts';await visit(next);}}for(const seed of ['package.json','package-lock.json','tsconfig.json','vitest.config.ts','src/test/utils/gradleOwnedS0cNative.test.ts'])await visit(seed);const files=Object.fromEntries([...seen].sort(([a],[b])=>a.localeCompare(b)));return {files,digest:hash(JSON.stringify(files))};}
const counters=['objects','bytes','parsedObjects','freshBytes','reads','lists','registryClosureBytes','anchorClosureBytes','ownerBytesWithCopies','ownerObjectCopies','logicalBytes'];
const median=a=>{a=[...a].sort((a,b)=>a-b);return(a[2]+a[3])/2;};
export function analyzeS0c(r){need(r.schema==='cgp.s0c.measurements.v1'&&r.leaseMs===5000&&r.marginMs===500,'schema');need(r.productionApproved===false&&r.backendEligible===false&&r.cg0Proceed===false&&r.cg3Proceed===false&&r.originalReadsSkipped===0,'adoption');const profile={schema:'cgp.s0c.profile.v1',format:'compact-state-root-v1',buckets:16,rowsPerPage:16,pageBytes:65536,directoryBytes:65536,rootBytes:65536,decodedBytes:8388608,objects:4096,ioSkipping:false,productionApproved:false};const canonical=p=>'{'+Object.keys(p).sort().map(k=>JSON.stringify(k)+':'+JSON.stringify(p[k])).join(',')+'}';need(r.profile&&canonical(r.profile)===canonical(profile)&&hash(canonical(profile))===r.profileDigest,'profile');need(r.executionSources&&hash(JSON.stringify(r.executionSources.files))===r.executionSources.digest,'source_receipt');need(r.samples?.length===12,'sample_count');const seen=new Set(),groups=[];
 for(const s of r.samples){const id=s.cohort+'/'+s.cycles;need([1,2,3].includes(s.cohort)&&[0,1,2,4].includes(s.cycles)&&!seen.has(id),'sample_identity');seen.add(id);need(Number.isSafeInteger(s.records)&&s.records>0&&/^[a-f0-9]{64}$/.test(s.inputDigest)&&/^[a-f0-9]{64}$/.test(s.logicalDigest),'input');need(s.modes?.length===3&&s.modes.map(m=>m.mode).join(',')==='F,W,P','modes');const live=s.modes.filter(m=>m.status==='success').map(m=>m.mode);need(live.includes('F')&&live.includes('P'),'required_modes');need(s.orders?.length===6,'orders');for(const [i,o]of s.orders.entries()){const off=(i+1+s.cohort)%live.length;need(o.round===i+1&&JSON.stringify(o.modes)===JSON.stringify([...live.slice(off),...live.slice(0,off)]),'order');}
  for(const m of s.modes){if(m.status==='capacity'){need(m.mode==='W'&&/capacity_exhausted|budget_exceeded/.test(m.reason),'capacity');groups.push({cohort:s.cohort,cycles:s.cycles,records:s.records,mode:m.mode,status:'capacity'});continue;}need(m.status==='success'&&m.logicalDigest===s.logicalDigest&&m.observations?.length===6,'logical');need(Number.isFinite(m.buildMs)&&m.buildMs>0,'build_time');if(m.mode==='P')need(m.oldReaders?.registry===true&&m.oldReaders?.anchor===true,'legacy');const measured=m.observations[0].metrics,wall=[],parse=[];for(const [i,o]of m.observations.entries()){need(o.round===i+1&&o.logicalDigest===s.logicalDigest,'round');const x=o.metrics;for(const key of counters)need(Number.isSafeInteger(x[key])&&x[key]>0,'counter');need(x.logicalBytes<=8388608,'logical_capacity');need(x.objects<=4096&&x.bytes<=8388608&&x.objects===x.parsedObjects&&x.reads===x.objects&&x.freshBytes===x.bytes&&x.lists===2,'all_bytes');need(x.ownerBytesWithCopies===x.registryClosureBytes+x.anchorClosureBytes&&x.ownerBytesWithCopies>=x.bytes&&x.ownerObjectCopies>=x.objects,'owner_copies');need(x.originalReadsSkipped===0&&x.backendEligible===false&&x.profileApproved===false&&x.nativeIsolationVerified===false&&x.checkpointSyncIncluded===false,'metric_adoption');need(Number.isFinite(x.wallMs)&&x.wallMs>0&&x.wallMs<4500&&Number.isFinite(x.materializeMs)&&x.materializeMs>0&&x.materializeMs<=x.wallMs,'time');need(counters.every(key=>x[key]===measured[key]&&x[key]===m.metrics[key])&&x.logicalBytes===s.modes[0].observations[0].metrics.logicalBytes,'stable_workload');wall.push(x.wallMs);parse.push(x.materializeMs);}
   groups.push({cohort:s.cohort,cycles:s.cycles,records:s.records,mode:m.mode,status:'success',bytes:measured.bytes,ownerBytesWithCopies:measured.ownerBytesWithCopies,registryClosureBytes:measured.registryClosureBytes,anchorClosureBytes:measured.anchorClosureBytes,objects:measured.objects,medianWallMs:median(wall),medianMaterializeMs:median(parse),buildMs:m.buildMs});}
 }
 return {schema:'cgp.s0c.analysis.v1',groups,decision:{productionApproved:false,productionSpeedupEstablished:false,eightReadsEstablished:false,originalReadsSkipped:0,cg0Proceed:false,cg3Proceed:false,next:'estimate CGP-I1 call reduction; S0c delta/incremental materialization and five-owner comparison remain'},limitations:['isolated representation object store, no owner session or live authorization','fresh full-object IO and hashing, no suffix IO or cross-call cache','new compact signature/profile is test-only; no old-reader downgrade','checkpoint/journal resync not included in timed materializer','all historical roots are retained; no physical GC or migration authorization','warm rotating order, three independent cohorts; no five-owner throughput claim']};
}
